  ('silicon-dioxide', '二氧化硅', 'Silicon Dioxide', 'chemical', 'SiO₂', '[["熔点","1713 °C（石英）"],["密度","2.65 g/cm³"],["莫氏硬度","7"]]', '拉丁语', 'silex', '燧石（属格 silicis）', 'silicon 由 Davy 提议、Berzelius 沿用，取自 silex「燧石」；dioxide ← 希腊 di-「二」+ oxys「尖锐的、酸的」+ -ide', '["氧化物","主要成分"]', 2),
  ('mohs-hardness', '莫氏硬度', 'Mohs Hardness', 'metric', '', '[["标度","1–10"],["性质","序数而非线性：金刚石(10) 约为滑石(1) 的 1500 倍"],["基准","滑石 1 … 石英 7 … 刚玉 9"]]', '人名', 'Friedrich Mohs', '德国矿物学家 Friedrich Mohs（1773–1839），1812 年提出', '以人名命名，非古典词根。选型上，物料莫氏硬度 > 6 即需提高衬板等级并核算磨损成本', '["硬度","选型输入"]', 3),
  ('graphite', '石墨', 'Graphite', 'material', 'C', '[["莫氏硬度","1–2"],["密度","2.2 g/cm³"],["结构","层状，层间易滑移"]]', '希腊语', 'graphein', '书写（γράφειν）', 'graphein + -ite，因最初用作制笔材料（pencil lead 其实是石墨）；层间滑移使其既是润滑剂又是难磨物料', '["碳质","导电","易打滑"]', 4),
  ('liner', '衬板', 'Liner', 'component', '', '[["作用","隔离磨蚀，保护筒体/机壳"],["材质","高锰钢、陶瓷、橡胶、复合板"],["更换判据","厚度磨损至原厚 1/3"]]', '拉丁语', 'linea', '亚麻线（← linum「亚麻」）', 'line + -er，指「贴在内壁上的一层」；linea 由「拉直的亚麻线」引申为「线、界线」，同根词 linear、align', '["耐磨件","易损"]', 5),
  ('calcium-carbonate', '碳酸钙', 'Calcium Carbonate', 'chemical', 'CaCO₃', '[["分解温度","约 825 °C（1 atm）"],["密度","2.71 g/cm³"],["溶解性","难溶于水，遇酸放出 CO₂"]]', '拉丁语', 'calx + carbo', 'calx「石灰」＋ carbo「炭」', 'carbonate 的 -ate 是拉丁过去分词后缀 -atus 演化来的盐类标记；calx 同根词 chalk（白垩）、calculate（用石子计数）', '["碳酸盐","填料"]', 6),
  ('density', '密度', 'Density', 'metric', '', '[["单位","g/cm³"],["用途","计算磨内填充率与输送能力"],["注意","真密度 ≠ 堆密度"]]', '拉丁语', 'densus', '稠密的、浓厚的', 'densus + -ity；同根词 dense、condense、densify。与希腊语借词相比，density 是纯拉丁构成', '["物性","计算输入"]', 7),
  ('bentonite', '膨润土', 'Bentonite', 'material', '（蒙脱石为主）', '[["莫氏硬度","1–2"],["膨胀性","遇水显著膨胀"],["粉碎特性","湿态黏性大，易糊磨"]]', '地名', 'Fort Benton', '美国 Wyoming 州 Fort Benton 岩层', '以白垩纪 Benton Shale 命名；主矿物蒙脱石（montmorillonite）则得名于法国 Montmorillon', '["黏土","易糊磨"]', 8),
  ('hammer', '锤头', 'Hammer', 'component', '', '[["作用","高速冲击破碎，决定产品粒度上限"],["材质","高铬铸铁、双金属复合"],["工况","冲击 + 磨蚀复合磨损"]]', '古英语', 'hamor', '锤（原始日耳曼语 *hamaraz）', '可上溯至原始印欧语 *h₂eḱmō「尖石」，与希腊 akmon「铁砧」同源——「石器时代的石锤」留在了词里', '["易损件","冲击破碎"]', 9),
  ('barium-sulfate', '硫酸钡', 'Barium Sulfate', 'chemical', 'BaSO₄', '[["密度","4.5 g/cm³"],["溶解性","极难溶（Ksp ≈ 1.1×10⁻¹⁰）"],["用途","加重剂、白色填料、造影剂"]]', '希腊语', 'barys', '重的（βαρύς）', 'barium 由 barys 命名，因其密度大；sulfur 的词源有争议（一说与原始印欧语 *swel-「燃烧」相关），不宜断言为希腊词根', '["硫酸盐","高密度"]', 10),
  ('bulk-density', '堆密度', 'Bulk Density', 'metric', '', '[["单位","g/cm³ 或 kg/m³"],["含义","含颗粒间空隙的单位体积质量"],["典型值","水泥 1.0–1.3；粉煤灰 0.7–1.0"]]', '古诺斯语 + 拉丁语', 'búlki + densus', 'búlki「船货、货舱容量」＋ densus「稠密」', 'bulk 原指「船载货物」，由「整批、散装」引申为「堆积体」；同根词 bulky。堆密度直接决定料仓与输送设备规格', '["物性","设备规格"]', 11),
  ('bauxite', '铝土矿', 'Bauxite', 'material', 'Al(OH)₃（主要组分）', '[["莫氏硬度","1–3"],["密度","2.5 g/cm³"],["粉碎特性","含水高，湿磨易黏附、易堵"]]', '地名', 'Les Baux', '法国南部 Les Baux 村', '1821 年 Berthier 以产地命名；不是单一矿物而是混合物，硬度波动大，选型时须按实际矿点取样', '["铝原料","易黏附"]', 12),
  ('grinding-roller', '磨辊', 'Grinding Roller', 'component', '', '[["作用","在料床上碾压粉碎，液压加压"],["关键参数","辊压、辊面硬度、辊套磨损量"],["型式","锥辊 / 柱辊 / 轮胎辊"]]', '拉丁语', 'rotula', '小轮（rota「轮」的指小形式）', 'rotula → 古法语 rolle → 英语 roll；同根词 rotate、rotary、control（← contrarotulare「对照账册」）', '["立磨","核心件","易损"]', 13),
  ('sodium-hydroxide', '氢氧化钠', 'Sodium Hydroxide', 'chemical', 'NaOH', '[["熔点","318 °C"],["形态","白色片状/颗粒，强吸湿"],["水溶液","强碱，pH 14"]]', '中世纪拉丁语 + 希腊语', 'soda + hydōr', 'soda「碱」（词源不确定，或源自阿拉伯语 suwwād「盐生植物」）＋ hydōr「水」', 'hydroxide = hydro-（希腊 hydōr「水」）+ ox-（希腊 oxys「酸的」）+ -ide；soda 一词来源仍有争议，属「不确定」而非「希腊/拉丁」', '["强碱","腐蚀性"]', 14),
  ('cleavage', '解理', 'Cleavage', 'metric', '', '[["含义","沿特定晶面裂开的倾向"],["分级","极完全 / 完全 / 中等 / 不完全"],["影响","决定破碎后颗粒形状"]]', '古英语', 'clēofan', '劈开（原始日耳曼语 *kleubaną）', '与 cleave、cleft、cleaver 同源；同族词 cliff 亦出此根。解理发育的物料（方解石、萤石）易过粉碎', '["结构","破碎行为"]', 15),
