  ('grinding-table', '磨盘', 'Grinding Table', 'component', '', '[["作用","与磨辊形成料床，兼作物料输送"],["关键参数","盘径、转速、挡料圈高度"],["磨损","磨道区衬板磨损最快"]]', '拉丁语', 'tabula', '板、平板', 'table ← 古法语 table ← 拉丁 tabula；同根词 tablet、tabulate。磨盘英文也常直接叫 table（立磨语境）', '["立磨","料床"]', 17),
  ('sodium-carbonate', '碳酸钠', 'Sodium Carbonate', 'chemical', 'Na₂CO₃', '[["熔点","851 °C"],["溶解性","易溶于水，溶液呈碱性"],["俗称","纯碱、苏打"]]', '中世纪拉丁语 + 拉丁语', 'soda + carbo', 'soda「碱」＋ carbo「炭、木炭」', '与 sodium hydroxide 共用 soda；工业上「氨碱法（Solvay process）」是 19 世纪最重要的化工流程之一', '["碳酸盐","助熔剂"]', 18),
