  ('lithium-carbonate', '碳酸锂', 'Lithium Carbonate', 'chemical', 'Li₂CO₃', '[["熔点","723 °C"],["密度","2.11 g/cm³"],["溶解性","微溶于水"]]', '希腊语', 'lithos', '石（λίθος）', 'Arfwedson 1817 年从矿石中发现，故以 lithos「石」命名，以示与植物来源的钠、钾区别；同根词 lithography、monolith', '["锂盐","釉料"]', 30),
  ('sieve-residue', '筛余', 'Sieve Residue', 'metric', '', '[["含义","某孔径筛上的残留质量百分比"],["常用孔径","45 μm、80 μm"],["意义","比表面积之外的另一细度口径"]]', '古英语 + 拉丁语', 'sife + residuum', 'sife「筛」＋ residuum「余留物」', 'residuum ← residere「留在后面」（re- + sedere「坐」），同根词 reside、residual、sediment；sieve 为日耳曼语底层词', '["细度","质量控制"]', 31),
  ('limestone', '石灰石', 'Limestone', 'material', 'CaCO₃', '[["莫氏硬度","3"],["密度","2.6–2.8 g/cm³"],["粉碎特性","易碎但磨蚀性中等偏高"]]', '古英语', 'lim + stān', 'lim「黏合料、石灰」＋ stān「石」', 'lim 与拉丁 limus「泥」同源（同族词还有 loam）；英语里 lime 既指石灰也指椴树，是两个不同来源的同形词', '["碳酸盐","水泥原料"]', 32),
  ('cyclone', '旋风分离器', 'Cyclone Separator', 'component', '', '[["作用","借旋流离心力分离粗细粉"],["关键参数","筒径、入口风速、压降"],["效率","对 <10 μm 颗粒效率骤降"]]', '希腊语', 'kyklōn', '旋转的、旋风（κύκλων，← kyklos「圆环」）', 'kyklos 是「圆、轮」的通用词根（cycle、bicycle、circle 同族）；separator ← 拉丁 separare「分开」', '["分级","收尘"]', 33),
  ('stearic-acid', '硬脂酸', 'Stearic Acid', 'chemical', 'C₁₈H₃₆O₂', '[["熔点","69.6 °C"],["形态","白色片状固体"],["用途","助磨剂、脱模剂、润滑剂"]]', '希腊语', 'stear', '兽脂、硬脂（στέαρ，属格 steatos）', 'stear + -ic；同根词 stearin、stearate。作为水泥助磨剂可显著降低粉磨功耗并抑制团聚', '["助磨剂","表面活性"]', 34),
  ('grindability', '易磨性', 'Grindability', 'metric', '', '[["常用指标","Hardgrove 指数 HGI（易磨的煤约 50–60）"],["意义","决定磨机台时产量与单位电耗"],["注意","HGI 高＝易磨，方向易记反"]]', '古英语', 'grindan', '磨碎', 'grind + -able + -ity；同族词 ground（「磨过的」）、grist（待磨的谷物）。易磨性与硬度、解理、韧性共同决定', '["功耗","产能核算"]', 35),
