  ('expanded-chemical-copper-ii-sulfate', '硫酸铜(II)', 'Copper(II) Sulfate', 'chemical', 'CuSO4', '[["化学类别","硫酸盐盐或硫酸盐化合物"],["工艺相关性","可能出现在配料、浸出、表面改性或废水处理中"]]', '化学命名法', 'copper(II) + sulfate', '离子名称按化学命名法组合', '化学式按离子电荷配平；实际使用需结合纯度、浓度与安全数据表', '["化学品","扩充词库"]', 304),
