  ('expanded-chemical-copper-ii-hydroxide', '氢氧化铜(II)', 'Copper(II) Hydroxide', 'chemical', 'Cu(OH)2', '[["化学类别","氢氧化物盐或氢氧化物化合物"],["工艺相关性","可能出现在配料、浸出、表面改性或废水处理中"]]', '化学命名法', 'copper(II) + hydroxide', '离子名称按化学命名法组合', '化学式按离子电荷配平；实际使用需结合纯度、浓度与安全数据表', '["化学品","扩充词库"]', 312),
  ('river-sand', '河砂', 'River Sand', 'material', 'SiO₂（为主）', '[["莫氏硬度","6.5"],["密度","1.4–1.6 g/cm³（松散堆密度）"],["解理","无（颗粒集合体）"],["工程特性","粒形圆润，含泥量与级配是关键"]]', '英语复合词', 'river + sand', '河 + 砂', '河道冲积形成的天然砂，粒形圆润、含泥量可控，是建筑用砂的传统来源；现代因河道禁采，更多转向机制砂', '["物料","天然骨料","矿物"]', 313),
  ('expanded-chemical-copper-ii-fluoride', '氟化铜(II)', 'Copper(II) Fluoride', 'chemical', 'CuF2', '[["化学类别","氟化物盐或氟化物化合物"],["工艺相关性","可能出现在配料、浸出、表面改性或废水处理中"]]', '化学命名法', 'copper(II) + fluoride', '离子名称按化学命名法组合', '化学式按离子电荷配平；实际使用需结合纯度、浓度与安全数据表', '["化学品","扩充词库"]', 314),
