  ('expanded-chemical-copper-ii-silicate', '硅酸铜(II)', 'Copper(II) Silicate', 'chemical', 'CuSiO3', '[["化学类别","硅酸盐盐或硅酸盐化合物"],["工艺相关性","可能出现在配料、浸出、表面改性或废水处理中"]]', '化学命名法', 'copper(II) + silicate', '离子名称按化学命名法组合', '化学式按离子电荷配平；实际使用需结合纯度、浓度与安全数据表', '["化学品","扩充词库"]', 316),
