  ('silica-sand', '石英砂', 'Silica Sand', 'material', 'SiO₂', '[["莫氏硬度","7"],["密度","2.6–2.7 g/cm³"],["解理","与石英同（无解理，贝壳状断口）"],["工程特性","高硬强磨蚀，设备磨损显著"]]', '英语复合词', 'silica + sand', '二氧化硅 + 砂', '以石英为主要成分的天然砂，用于铸造、水处理与玻璃；硬度高、磨蚀性强，长期加工对泵体与管道磨损明显', '["物料","硅质原料","矿物"]', 327),
  ('expanded-chemical-zinc-nitrate', '硝酸锌', 'Zinc Nitrate', 'chemical', 'Zn(NO3)2', '[["化学类别","硝酸盐盐或硝酸盐化合物"],["工艺相关性","可能出现在配料、浸出、表面改性或废水处理中"]]', '化学命名法', 'zinc + nitrate', '离子名称按化学命名法组合', '化学式按离子电荷配平；实际使用需结合纯度、浓度与安全数据表', '["化学品","扩充词库"]', 328),
  ('manufactured-sand', '机制砂', 'Manufactured Sand', 'material', '', '[["莫氏硬度","7"],["密度","1.5–1.7 g/cm³（松散堆密度）"],["解理","取决于母岩"],["工程特性","石粉含量与粒形决定成品质量"]]', '英语复合词', 'manufactured + sand', '加工的 + 砂', '由岩石破碎、整形、筛分制成的砂，替代天然砂；粒形、石粉含量与级配是关键控制指标，母岩硬度直接影响成品性能', '["物料","人工骨料","矿物"]', 329),
  ('expanded-chemical-zinc-phosphate', '磷酸锌', 'Zinc Phosphate', 'chemical', 'Zn3(PO4)2', '[["化学类别","磷酸盐盐或磷酸盐化合物"],["工艺相关性","可能出现在配料、浸出、表面改性或废水处理中"]]', '化学命名法', 'zinc + phosphate', '离子名称按化学命名法组合', '化学式按离子电荷配平；实际使用需结合纯度、浓度与安全数据表', '["化学品","扩充词库"]', 330),
