  ('expanded-chemical-zinc-hydroxide', '氢氧化锌', 'Zinc Hydroxide', 'chemical', 'Zn(OH)2', '[["化学类别","氢氧化物盐或氢氧化物化合物"],["工艺相关性","可能出现在配料、浸出、表面改性或废水处理中"]]', '化学命名法', 'zinc + hydroxide', '离子名称按化学命名法组合', '化学式按离子电荷配平；实际使用需结合纯度、浓度与安全数据表', '["化学品","扩充词库"]', 332),
  ('tourmaline', '电气石', 'Tourmaline', 'material', '（复杂硼硅酸盐）', '[["莫氏硬度","7.25"],["密度","3.0–3.2 g/cm³"],["解理","差，贝壳状断口"],["工程特性","硬度高、无解理，破碎后颗粒多棱角"]]', '僧伽罗语', 'tōramalli', '（僧伽罗语，指该宝石）', '经荷兰语进入欧洲语言，源自僧伽罗语 tōramalli；具压电与热电性，摩擦可生电，故中文称「电气石」，工业用作压电材料与滤料', '["物料","硼硅酸盐","矿物"]', 333),
